def largest_subset(nums):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def is_divisible(a, b):
        return a % b == 0 or b % a == 0

    nums.sort()
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if is_divisible(nums[i], nums[j]):
